
CREATE TABLE p_accounting_settings(singleton INTEGER PRIMARY KEY CHECK(singleton=1),authority TEXT NOT NULL CHECK(authority IN ('quickbooks','stripe','xero','pantry')),account_id TEXT NOT NULL,item_id TEXT NOT NULL,tax_code TEXT NOT NULL,income_account TEXT NOT NULL,clearing_account TEXT NOT NULL,fee_account TEXT NOT NULL,bank_account TEXT NOT NULL,remittance TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),authorized_by TEXT NOT NULL REFERENCES oa_operators(id),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE p_amounts(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES p_acceptances(proposal_id),schedule_key TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('deposit','milestone','recurring')),label TEXT NOT NULL,cents INTEGER NOT NULL CHECK(cents>0),currency TEXT NOT NULL,issue_on TEXT,due_on TEXT,net_days INTEGER NOT NULL,issued_at INTEGER,external_id TEXT,external_account TEXT,accounting_status TEXT NOT NULL DEFAULT 'scheduled',remote_paid_cents INTEGER NOT NULL DEFAULT 0,mismatch TEXT,version INTEGER NOT NULL DEFAULT 1,UNIQUE(proposal_id,schedule_key));
CREATE TABLE p_payment_allocations(payment_id TEXT PRIMARY KEY REFERENCES p_payment_records(id),amount_id TEXT NOT NULL REFERENCES p_amounts(id),cents INTEGER NOT NULL CHECK(cents>0));
CREATE TABLE p_financial_events(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,event_type TEXT NOT NULL,object_id TEXT NOT NULL,created_at INTEGER NOT NULL,received_at INTEGER NOT NULL,body_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('claimed','processed','held')),amount_id TEXT REFERENCES p_amounts(id),payment_state TEXT);
CREATE TABLE p_provider_payments(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,amount_id TEXT NOT NULL REFERENCES p_amounts(id),charge_id TEXT,state TEXT NOT NULL CHECK(state IN ('scheduled','processing','succeeded','failed','refunded','partially_refunded','disputed')),cents INTEGER NOT NULL CHECK(cents>0),refunded_cents INTEGER NOT NULL DEFAULT 0,dispute_status TEXT,last_event TEXT NOT NULL REFERENCES p_financial_events(id));
CREATE TABLE p_accounting_requests(id TEXT PRIMARY KEY,authority TEXT NOT NULL,account_id TEXT NOT NULL,kind TEXT NOT NULL,subject TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('claimed','succeeded','held')),external_id TEXT,created_at INTEGER NOT NULL,UNIQUE(authority,account_id,kind,subject));
CREATE TABLE p_accounting_customers(client_id TEXT NOT NULL REFERENCES p_clients(id),authority TEXT NOT NULL,account_id TEXT NOT NULL,external_id TEXT NOT NULL,PRIMARY KEY(client_id,authority,account_id));
CREATE TABLE p_offline_requests(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES p_payment_records(id),amount_id TEXT NOT NULL REFERENCES p_amounts(id),fingerprint TEXT NOT NULL,UNIQUE(amount_id,fingerprint));
CREATE TABLE p_clearing_postings(id TEXT PRIMARY KEY,authority TEXT NOT NULL,account_id TEXT NOT NULL,source_id TEXT NOT NULL,kind TEXT NOT NULL,cents INTEGER NOT NULL,clearing_delta INTEGER NOT NULL,fee_delta INTEGER NOT NULL,bank_delta INTEGER NOT NULL,external_id TEXT,UNIQUE(authority,account_id,kind,source_id));

CREATE TABLE p_accounting_authority(singleton INTEGER PRIMARY KEY CHECK(singleton=1),settings_version INTEGER NOT NULL,authorized_by TEXT NOT NULL REFERENCES oa_operators(id));

CREATE UNIQUE INDEX p_one_external_invoice ON p_amounts(external_account,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE p_accounting_catalog(catalog_id TEXT NOT NULL REFERENCES p_priced_catalog(id),authority TEXT NOT NULL,account_id TEXT NOT NULL,item_id TEXT NOT NULL,tax_code TEXT NOT NULL,income_account TEXT NOT NULL,PRIMARY KEY(catalog_id,authority,account_id));

CREATE TABLE p_remittance_settings(singleton INTEGER PRIMARY KEY CHECK(singleton=1),instructions TEXT NOT NULL,updated_by TEXT NOT NULL REFERENCES oa_operators(id),updated_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1);
